# 같은 종목 시세가 여러 번 오면 버전이 가장 큰 것 하나만 남긴다 — 순서가 뒤바뀌어 와도
ticks = [("005930", 1, 71000), ("000660", 1, 182000), ("005930", 3, 71500), ("005930", 2, 70900)]
prev_close = {"005930": 70000, "000660": 190000}
latest = {}
for code, ver, price in ticks:
    if code not in latest or latest[code][0] < ver:
        latest[code] = (ver, price)
rows = []
for code, (ver, price) in latest.items():
    chg = (price - prev_close[code]) / prev_close[code] * 100
    rows.append((chg, code, ver, price))
for chg, code, ver, price in sorted(rows, reverse=True):
    print(code, "버전", ver, price, f"{chg:+.2f}%")
# 005930 버전 3 71500 +2.14%
# 000660 버전 1 182000 -4.21%

# 지식 그래프에서 홉마다 점수 상위 k 개만 다음 홉으로 넘긴다 (빔 탐색)
graph = {
    "이벤트:리튬 가격 급락": [("영향", "산업:양극재", 0.9), ("영향", "산업:전기차", 0.6), ("언급", "국가:칠레", 0.2)],
    "산업:양극재": [("속함", "종목:A화학", 0.8), ("속함", "종목:B소재", 0.7), ("속함", "종목:C머티", 0.3)],
    "산업:전기차": [("속함", "종목:D모터스", 0.7), ("속함", "종목:E오토", 0.4)],
    "국가:칠레": [("관련", "종목:F광업", 0.5)],
}
def search(start, hops, k):
    beam = [(1.0, [start])]
    seen_paths = 0
    for _ in range(hops):
        cand = []
        for score, path in beam:
            for rel, nxt, w in graph.get(path[-1], []):
                cand.append((score * w, path + [nxt]))
        seen_paths += len(cand)
        beam = sorted(cand, reverse=True)[:k]
    return beam, seen_paths
for k in (2, 10):
    beam, n = search("이벤트:리튬 가격 급락", 2, k)
    print(f"k={k} 본 경로 {n}개 →", [(round(s, 2), p[-1]) for s, p in beam[:3]])
# k=2 본 경로 8개 → [(0.72, '종목:A화학'), (0.63, '종목:B소재')]
# k=10 본 경로 9개 → [(0.72, '종목:A화학'), (0.63, '종목:B소재'), (0.42, '종목:D모터스')]

import json
# LLM 이 뉴스에서 뽑은 결과를 받기 전에 검사한다 — 형식·사전·근거
master = {"005930": "삼성전자", "000660": "SK하이닉스"}
article = "SK하이닉스가 HBM 공급 계약을 발표했다. 삼성전자는 언급되지 않았다."
outputs = [
    '{"ticker": "000660", "event": "공급계약", "polarity": "positive", "evidence": "HBM 공급 계약을 발표"}',
    '{"ticker": "005935", "event": "공급계약", "polarity": "positive", "evidence": "HBM 공급 계약을 발표"}',
    '{"ticker": "000660", "event": "공급계약", "polarity": "great", "evidence": "HBM 공급 계약을 발표"}',
    '{"ticker": "000660", "event": "공급계약", "polarity": "positive", "evidence": "3조원 규모 계약"}',
    'SK하이닉스 호재입니다',
]
EVENTS = {"실적", "공급계약", "인수합병", "소송"}
def check(raw):
    try:
        o = json.loads(raw)
    except json.JSONDecodeError:
        return "형식 오류"
    if o.get("ticker") not in master:
        return "없는 종목코드"
    if o.get("event") not in EVENTS or o.get("polarity") not in {"positive", "negative", "neutral"}:
        return "허용 밖 값"
    if o.get("evidence", "") not in article:
        return "근거가 원문에 없음"
    return "통과"
for raw in outputs:
    print(check(raw))
# 통과
